configuration.jsScript:
if (metadata.originatorType === 'ASSET') {
    if (msg.bulk_command !== undefined && msg.bulk_command !== null) {
        return ['bulk_command'];
    }
    return ['asset_other'];
}
return ['device'];

switch (msg.type) {
    case 'device_command':    return ['bulk_command'];
    case 'bulk_command':      return ['bulk_command'];
    case 'send_notification': return ['notification'];
    case 'delay':             return ['delay'];
    default:                  return ['unknown'];
}

var out;
if (msg.type === 'device_command') {
    out = {
        mode:       'device_list',
        device_ids: [msg.device_id],
        command:    msg.command,
        params:     msg.params || {}
    };
} else {
    out = {
        mode:          msg.mode || 'device_list',
        device_ids:    msg.device_ids,
        room_asset_id: msg.room_asset_id,
        home_asset_id: msg.home_asset_id,
        command:       msg.command,
        params:        msg.params || {},
        filter_type:   msg.filter_type || null
    };
}
return {msg: out, metadata: metadata, msgType: 'BULK_COMMAND'};

configuration.alarmDetailsBuildJs:
var d = {};
d.message  = msg.message  || 'Automation triggered';
d.ruleName = metadata.actionRuleName || '';
return d;

configuration.jsScript:
var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId    || 'direct',
        rule_name:      metadata.actionRuleName  || 'direct_command',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || metadata.triggerDeviceId || 'app',
        status:         'success',
        total:          msg.totalDevices  || 0,
        success_count:  msg.successCount  || 0,
        failed_count:   msg.failedCount   || 0
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};

var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId   || 'unknown',
        rule_name:      metadata.actionRuleName || 'unknown',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || metadata.triggerDeviceId || 'app',
        status:         'failed',
        total:          msg.totalDevices  || 0,
        success_count:  msg.successCount  || 0,
        failed_count:   msg.failedCount   || 0,
        error:          msg.error         || 'evaluation_or_rpc_failed',
        results:        msg.results       || []
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};

var bc = msg.bulk_command;
var out = {
    mode:          bc.mode          || 'device_list',
    device_ids:    bc.device_ids,
    room_asset_id: bc.room_asset_id,
    home_asset_id: bc.home_asset_id,
    command:       bc.command,
    params:        bc.params        || {},
    filter_type:   bc.filter_type   || null
};
var newMeta = metadata;
newMeta.triggerDeviceName = 'app';
newMeta.triggerDeviceId   = metadata.originatorId || 'app';
newMeta.triggerTimestamp  = String(new Date().getTime());
newMeta.actionRuleId      = 'direct';
newMeta.actionRuleName    = 'app_direct_command';
return {msg: out, metadata: newMeta, msgType: 'BULK_COMMAND'};
